 values(v_unit_id,v_package.expression_id,v_package.id,'virginia-house-wife:1824:semantic:soup-with-bouilli',v_gravy_unit,10,'branched_soup_and_bouilli_service_protocol','SOUP WITH BOUILLI.','verified',0.99,'source_text_verified_semantic_extraction_v1',
 jsonb_build_object('printed_pages',jsonb_build_array(30,31),'primary_function','derive a soup-and-bouilli service from the preceding soup process, preserving broth while finishing beef and gravy separately','historical_container','unheaded soup instruction sequence','modern_safety_assessed',false,'modern_normalization_applied',false,
 'human_visual_inspection',false,'atlas_execution_requires_downstream_normalization',true,'depends_on_unit_key','virginia-house-wife:1824:semantic:gravy-soup','process_branches',jsonb_build_array('hot_soup','bouilli_beef','gravy')),
