 (2,'inherit-base','recipe_dependency','bouilli_soup','inherit_recipe_from','virginia-house-wife:1824:semantic:gravy-soup',null,null,null,'base soup preparation','every thing directed for the other soup; exactly same way',0.99,jsonb_build_object('dependency_type','ingredients_and_process'),jsonb_build_array(30),true),
 (3,'start-earlier','relative_timing','bouilli_soup','start_earlier_than','preceding soup schedule',1::numeric,'hour','one hour sooner','meal scheduling','to allow time to prepare bouilli',0.99,jsonb_build_object('planning_dependency',true),jsonb_build_array(30),false),
